// Local storage based client for offline/local mode
// Stores thoughts in browser's localStorage for persistence

// Helper functions for localStorage management
const STORAGE_KEY = 'trace_app_thoughts';

const getStoredThoughts = () => {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    return stored ? JSON.parse(stored) : getDefaultThoughts();
  } catch (error) {
    console.error('Error loading thoughts from localStorage:', error);
    return getDefaultThoughts();
  }
};

const saveThoughts = (thoughts) => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(thoughts));
  } catch (error) {
    console.error('Error saving thoughts to localStorage:', error);
  }
};

const getDefaultThoughts = () => [
  {
    id: '1',
    statement: 'I believe that continuous learning is essential for personal growth',
    reasoning: 'Every day I encounter new information that challenges my worldview',
    evidence: 'Reading books, taking courses, and learning new skills has always helped me improve',
    confidence: 8,
    what_would_change: 'If scientific research showed that fixed intelligence leads to better outcomes',
    reflections: [],
    ai_reflections: [],
    is_archived: false,
    created_date: new Date('2024-01-15').toISOString()
  },
  {
    id: '2',
    statement: 'I believe that honest communication builds stronger relationships',
    reasoning: 'Hidden issues tend to fester and cause bigger problems later',
    evidence: 'When I\'ve been honest with friends and family, our relationships have deepened',
    confidence: 9,
    what_would_change: 'If evidence showed that strategic deception led to better long-term outcomes',
    reflections: [],
    ai_reflections: [],
    is_archived: false,
    created_date: new Date('2024-01-10').toISOString()
  }
];

export const base44 = {
  auth: {
    me: async () => ({ id: 'local-user', email: 'local@example.com', name: 'Local User' }),
    logout: () => { console.log('Logout called (local mode)'); },
    redirectToLogin: () => { console.log('Redirect to login called (local mode)'); }
  },
  appLogs: {
    logUserInApp: async (pageName) => {
      console.log('User navigated to:', pageName);
      return { success: true };
    }
  },
  entities: {
    Belief: {
      findMany: async () => getStoredThoughts(),
      list: async (orderBy, limit) => getStoredThoughts().slice(0, limit || 100),
      findUnique: async ({ where }) => getStoredThoughts().find(b => b.id === where.id),
      create: async (args) => {
        const thoughts = getStoredThoughts();
        const newBelief = { 
          ...args.data, 
          id: String(Date.now()),
          created_date: new Date().toISOString(),
          reflections: [],
          ai_reflections: [],
          is_archived: false
        };
        thoughts.push(newBelief);
        saveThoughts(thoughts);
        return newBelief;
      },
      update: async (args) => {
        const thoughts = getStoredThoughts();
        const idx = thoughts.findIndex(b => b.id === args.where.id);
        if (idx >= 0) {
          thoughts[idx] = { ...thoughts[idx], ...args.data };
          saveThoughts(thoughts);
          return thoughts[idx];
        }
        return null;
      },
      delete: async ({ where }) => {
        const thoughts = getStoredThoughts();
        const idx = thoughts.findIndex(b => b.id === where.id);
        if (idx >= 0) {
          thoughts.splice(idx, 1);
          saveThoughts(thoughts);
        }
        return { id: where.id };
      }
    },
    Thought: {
      findMany: async () => getStoredThoughts(),
      list: async (orderBy, limit) => getStoredThoughts().slice(0, limit || 100),
      findUnique: async ({ where }) => getStoredThoughts().find(b => b.id === where.id),
      create: async (args) => {
        console.log('Create function called with args:', args);
        const thoughts = getStoredThoughts();
        const newThought = { 
          id: String(Date.now()),
          created_date: new Date().toISOString(),
          reflections: [],
          ai_reflections: [],
          is_archived: false,
          ...args  // Spread args directly, not args.data
        };
        console.log('New thought to save:', newThought);
        thoughts.push(newThought);
        saveThoughts(thoughts);
        console.log('Saved thoughts:', getStoredThoughts());
        return newThought;
      },
      update: async (args) => {
        const thoughts = getStoredThoughts();
        const idx = thoughts.findIndex(b => b.id === args.where.id);
        if (idx >= 0) {
          thoughts[idx] = { ...thoughts[idx], ...args.data };
          saveThoughts(thoughts);
          return thoughts[idx];
        }
        return null;
      },
      delete: async ({ where }) => {
        const thoughts = getStoredThoughts();
        const idx = thoughts.findIndex(b => b.id === where.id);
        if (idx >= 0) {
          thoughts.splice(idx, 1);
          saveThoughts(thoughts);
        }
        return { id: where.id };
      }
    }
  },
  functions: {
    invoke: async (name, args) => {
      console.log('Function invoke called (local mode):', name, args);
      return null;
    }
  }
};
